  const who = { photo: "photos", video: "videos and photos", pdf: "PDF files and images", media: "recordings, camera images and screen captures" }[c];
  if (n === "Speech to Text") q.push(["Is my voice sent to ToolsNest?", "ToolsNest does not receive or store your voice. Your browser captures the audio, and in Chrome speech recognition is usually handled by the browser's own speech service under its privacy policy."]);
